from decimal import Decimal, ROUND_HALF_UP, Context, InvalidOperation

def floatformat_original(text, arg):
    """Original floatformat logic with the bug"""
    try:
        input_val = repr(text)
        d = Decimal(input_val)  # Bug is here: repr(Decimal) can't be parsed
    except InvalidOperation:
        try:
            d = Decimal(str(float(text)))
        except (ValueError, InvalidOperation, TypeError):
            return ""
    return format_decimal(d, arg)

def floatformat_fixed(text, arg):
    """Fixed floatformat logic"""
    try:
        input_val = repr(text)
        d = Decimal(text)  # Fixed: pass text directly
    except InvalidOperation:
        try:
            d = Decimal(str(float(text)))
        except (ValueError, InvalidOperation, TypeError):
            return ""
    return format_decimal(d, arg)

def format_decimal(d, p):
    try:
        m = int(d) - d
    except (ValueError, OverflowError, InvalidOperation):
        return repr(d)

    exp = Decimal(1).scaleb(-abs(p))
    tupl = d.as_tuple()
    units = len(tupl[1])
    units += -tupl[2] if m else tupl[2]
    prec = abs(p) + units + 1

    rounded_d = d.quantize(exp, ROUND_HALF_UP, Context(prec=prec))
    sign, digits, exponent = rounded_d.as_tuple()
    digits = [str(digit) for digit in reversed(digits)]
    while len(digits) <= abs(exponent):
        digits.append("0")
    digits.insert(-exponent, ".")
    if sign and rounded_d:
        digits.append("-")
    return "".join(reversed(digits))

# Test with Decimal
d = Decimal('42.12345678901234567890')
print("Testing with Decimal('42.12345678901234567890'):")
print("Original:", floatformat_original(d, 20))
print("Fixed:   ", floatformat_fixed(d, 20))
print("Expected:", "42.12345678901234567890")
print()

