f = 42.123456789012345
print("Testing with float 42.123456789012345:")
print("Original:", floatformat_original(f, 20))
print("Fixed:   ", floatformat_fixed(f, 20))
print()

# Test with string
s = "42.12345678901234567890"
print("Testing with string '42.12345678901234567890':")
print("Original:", floatformat_original(s, 20))
print("Fixed:   ", floatformat_fixed(s, 20))
